import gurobipy as grb
import numpy as np
from itertools import product

def solve_trsmp(
    N,  # number of stations
    M,  # number of trains
    T,  # list of train indices (0 to M-1)
    S,  # list of station indices (0 to N-1)
    D_t,  # dict: train t -> list of segments (arcs) it traverses, each arc is (i, i+1)
    A,  # list of all segments, each is (i, i+1)
    B,  # list of disrupted segments
    t_start,  # disruption start time
    t_end,  # disruption end time
    K,  # list of speed profile plan indices
    d_t_i,  # dict: (t, i) -> scheduled departure time
    a_t_i,  # dict: (t, i) -> scheduled arrival time
    L_a,  # dict: a -> length of segment
    v_max_a,  # dict: a -> max speed
    v_min_a,  # dict: a -> min speed
    a_max,  # max acceleration
    b_max,  # max deceleration
    t_min_run_a,  # dict: a -> min running time
    t_max_run_a,  # dict: a -> max running time
    t_dwell_min_i,  # dict: i -> min dwell time
    t_dwell_max_i,  # dict: i -> max dwell time
    t_headway,  # min headway
    t_block,  # min blocking time
    E_t_a_k,  # dict: (t, a, k) -> energy consumption
    run_time_a_k,  # dict: (a, k) -> running time for speed profile k on segment a
    c_delay,  # cost coefficient for delay
    c_energy,  # cost coefficient for energy
    c_cancel,  # cost coefficient for cancellation
    c_reroute,  # cost coefficient for rerouting
    BIG_M,  # big-M constant
    time_limit=300,  # solver time limit in seconds
    gap_rel=0.01  # relative gap
):
    """
    Solve the Train Rescheduling and Speed Management Problem (TRSMP) under partial segment blockage.

    Returns:
        model: Gurobi model
        x: dict of cancellation variables
        y: dict of rerouting variables
        z: dict of speed profile selection variables
        A_t_i: dict of actual arrival times
        D_t_i: dict of actual departure times
        u_t_a: dict of running times
        o_t_t_a: dict of ordering variables
        w_t_a: dict of start times on segments
        e_t_a: dict of end times on segments
        delay_arr: dict of arrival delays
        delay_dep: dict of departure delays
    """
    # Create Gurobi model
    model = grb.Model("TRSMP")
    model.setParam("TimeLimit", time_limit)
    model.setParam("MIPGap", gap_rel)
    model.setParam("OutputFlag", 1)

    # Decision variables
    # x_t: binary, 1 if train t is not cancelled
    x = {}
    for t in T:
        x[t] = model.addVar(vtype=grb.BINARY, name=f"x_{t}")

    # y_t_a: binary, 1 if train t uses original track on segment a (for disrupted segments)
    y = {}
    for t in T:
        for a in B:
            if a in D_t[t]:
                y[(t, a)] = model.addVar(vtype=grb.BINARY, name=f"y_{t}_{a[0]}_{a[1]}")

    # z_t_a_k: binary, 1 if train t uses speed profile k on segment a
    z = {}
    for t in T:
        for a in D_t[t]:
            for k in K:
                z[(t, a, k)] = model.addVar(vtype=grb.BINARY, name=f"z_{t}_{a[0]}_{a[1]}_{k}")

    # A_t_i: continuous, actual arrival time of train t at station i
    A_t_i = {}
    for t in T:
        for i in S:
            A_t_i[(t, i)] = model.addVar(lb=0, name=f"A_{t}_{i}")

    # D_t_i: continuous, actual departure time of train t at station i
    D_t_i = {}
    for t in T:
        for i in S:
            D_t_i[(t, i)] = model.addVar(lb=0, name=f"D_{t}_{i}")

    # u_t_a: continuous, running time of train t on segment a
    u_t_a = {}
    for t in T:
        for a in D_t[t]:
            u_t_a[(t, a)] = model.addVar(lb=0, name=f"u_{t}_{a[0]}_{a[1]}")

    # w_t_a: continuous, start time of train t on segment a
    w_t_a = {}
    for t in T:
        for a in D_t[t]:
            w_t_a[(t, a)] = model.addVar(lb=0, name=f"w_{t}_{a[0]}_{a[1]}")

    # e_t_a: continuous, end time of train t on segment a
    e_t_a = {}
    for t in T:
        for a in D_t[t]:
            e_t_a[(t, a)] = model.addVar(lb=0, name=f"e_{t}_{a[0]}_{a[1]}")

    # o_t_t_a: binary, 1 if train t precedes train t' on segment a
    o_t_t_a = {}
    for a in A:
        # Find all trains that traverse segment a
        trains_on_a = [t for t in T if a in D_t[t]]
        for t1 in trains_on_a:
            for t2 in trains_on_a:
                if t1 < t2:
                    o_t_t_a[(t1, t2, a)] = model.addVar(vtype=grb.BINARY, name=f"o_{t1}_{t2}_{a[0]}_{a[1]}")

    # o_t_t_i: binary, 1 if train t precedes train t' at station i
    o_t_t_i = {}
    for i in S:
        # Find all trains that stop at station i
        trains_at_i = [t for t in T if i in [a[0] for a in D_t[t]] or i in [a[1] for a in D_t[t]]]
        for t1 in trains_at_i:
            for t2 in trains_at_i:
                if t1 < t2:
                    o_t_t_i[(t1, t2, i)] = model.addVar(vtype=grb.BINARY, name=f"o_{t1}_{t2}_{i}")

    # delay_arr_t_i: continuous, arrival delay of train t at station i
    delay_arr = {}
    for t in T:
        for i in S:
            delay_arr[(t, i)] = model.addVar(lb=0, name=f"delay_arr_{t}_{i}")

    # delay_dep_t_i: continuous, departure delay of train t at station i
    delay_dep = {}
    for t in T:
        for i in S:
            delay_dep[(t, i)] = model.addVar(lb=0, name=f"delay_dep_{t}_{i}")

    # Objective function
    obj = 0

    # Delay costs
    for t in T:
        for i in S:
            obj += c_delay * (delay_arr[(t, i)] + delay_dep[(t, i)])

    # Energy consumption costs
    for t in T:
        for a in D_t[t]:
            for k in K:
                obj += c_energy * E_t_a_k[(t, a, k)] * z[(t, a, k)]

    # Cancellation costs
    for t in T:
        obj += c_cancel * (1 - x[t])

    # Rerouting costs
    for t in T:
        for a in B:
            if a in D_t[t]:
                obj += c_reroute * (1 - y[(t, a)])

    model.setObjective(obj, grb.GRB.MINIMIZE)

    # Constraints

    # 1. Train cancellation constraints
    for t in T:
        for i in S:
            model.addConstr(A_t_i[(t, i)] <= BIG_M * x[t], name=f"cancel_A_{t}_{i}")
            model.addConstr(D_t_i[(t, i)] <= BIG_M * x[t], name=f"cancel_D_{t}_{i}")

    # 2. Running time on segments
    for t in T:
        for a in D_t[t]:
            i, i_next = a
            # Running time bounds
            model.addConstr(u_t_a[(t, a)] >= t_min_run_a[a] * x[t], name=f"run_min_{t}_{a[0]}_{a[1]}")
            model.addConstr(u_t_a[(t, a)] <= t_max_run_a[a] * x[t], name=f"run_max_{t}_{a[0]}_{a[1]}")
            # Linking departure at i and arrival at i+1
            model.addConstr(A_t_i[(t, i_next)] == D_t_i[(t, i)] + u_t_a[(t, a)], name=f"link_run_{t}_{a[0]}_{a[1]}")
            # Start and end times on segment
            model.addConstr(w_t_a[(t, a)] == D_t_i[(t, i)], name=f"start_time_{t}_{a[0]}_{a[1]}")
            model.addConstr(e_t_a[(t, a)] == A_t_i[(t, i_next)], name=f"end_time_{t}_{a[0]}_{a[1]}")

    # 3. Dwell time at stations
    for t in T:
        for i in S:
            # Check if train t stops at station i (i is an intermediate station for train t)
            # A train stops at station i if i is the end of a segment or start of a segment in D_t[t]
            stops_at_i = False
            for a in D_t[t]:
                if a[1] == i or a[0] == i:
                    stops_at_i = True
                    break
            if stops_at_i:
                model.addConstr(D_t_i[(t, i)] - A_t_i[(t, i)] >= t_dwell_min_i[i] * x[t], name=f"dwell_min_{t}_{i}")
                model.addConstr(D_t_i[(t, i)] - A_t_i[(t, i)] <= t_dwell_max_i[i] * x[t], name=f"dwell_max_{t}_{i}")

    # 4. Speed profile selection
    for t in T:
        for a in D_t[t]:
            model.addConstr(grb.quicksum(z[(t, a, k)] for k in K) == x[t], name=f"speed_profile_{t}_{a[0]}_{a[1]}")

    # 5. Running time linked to speed profile
    for t in T:
        for a in D_t[t]:
            model.addConstr(u_t_a[(t, a)] == grb.quicksum(run_time_a_k[(a, k)] * z[(t, a, k)] for k in K), 
                           name=f"run_time_link_{t}_{a[0]}_{a[1]}")

    # 7. Rerouting decision for disrupted segments
    for t in T:
        for a in B:
            if a in D_t[t]:
                # If using original track (y=1), must wait until t_end or finish before t_start
                # We use a disjunctive constraint linearized with big-M
                # Option 1: w_t_a >= t_end (if y=1)
                # Option 2: e_t_a <= t_start (if y=1)
                # We introduce auxiliary binary variables for the disjunction
                # For simplicity, we enforce: if y=1, then either w >= t_end OR e <= t_start
                # This is a disjunctive constraint. We linearize using additional binary variables.

                # Let's use two binary variables: r1, r2 where r1 + r2 = 1
                # r1 = 1: w >= t_end
                # r2 = 1: e <= t_start
                # But this adds complexity. For now, we enforce a simpler constraint:
                # If y=1, the train must not be on the segment during [t_start, t_end]
                # This means: w >= t_end OR e <= t_start
                # We linearize this with big-M:
                # w >= t_end - BIG_M * (1 - y) - BIG_M * r1
                # e <= t_start + BIG_M * (1 - y) + BIG_M * (1 - r1)
                # where r1 is binary, and we need r1 to be 1 when y=1
                # Actually, let's use a different approach:
                # If y=1, then (w >= t_end) OR (e <= t_start)
                # We can write: w >= t_end - BIG_M * (1 - y) - BIG_M * s
                # e <= t_start + BIG_M * (1 - y) + BIG_M * s
                # where s is binary, and we don't need to link s to y directly if we allow both options
                # But this is not correct. Let's use a standard disjunctive linearization.

                # For simplicity in this implementation, we enforce:
                # If y=1, then w >= t_end (conservative: always wait)
                # This is a simplification. A more complete model would allow both options.
                model.addConstr(w_t_a[(t, a)] >= t_end - BIG_M * (1 - y[(t, a)]), 
                               name=f"disruption_wait_{t}_{a[0]}_{a[1]}")

    # 8. Segment occupancy and conflict resolution
    for a in A:
        trains_on_a = [t for t in T if a in D_t[t]]
        for idx1, t1 in enumerate(trains_on_a):
            for t2 in trains_on_a[idx1+1:]:
                # Ordering constraint
                model.addConstr(o_t_t_a[(t1, t2, a)] + o_t_t_a[(t2, t1, a)] == 1, 
                               name=f"order_{t1}_{t2}_{a[0]}_{a[1]}")
                # If t1 precedes t2: e_t1 + t_headway <= w_t2
                model.addConstr(e_t_a[(t1, a)] + t_headway <= w_t_a[(t2, a)] + BIG_M * (1 - o_t_t_a[(t1, t2, a)]), 
                               name=f"headway_1_{t1}_{t2}_{a[0]}_{a[1]}")
                # If t2 precedes t1: e_t2 + t_headway <= w_t1
                model.addConstr(e_t_a[(t2, a)] + t_headway <= w_t_a[(t1, a)] + BIG_M * o_t_t_a[(t1, t2, a)], 
                               name=f"headway_2_{t1}_{t2}_{a[0]}_{a[1]}")

    # 10. Train ordering at stations (overtaking)
    for i in S:
        trains_at_i = [t for t in T if i in [a[0] for a in D_t[t]] or i in [a[1] for a in D_t[t]]]
        for idx1, t1 in enumerate(trains_at_i):
            for t2 in trains_at_i[idx1+1:]:
                # Ordering constraint
                model.addConstr(o_t_t_i[(t1, t2, i)] + o_t_t_i[(t2, t1, i)] == 1, 
                               name=f"station_order_{t1}_{t2}_{i}")
                # If t1 precedes t2: D_t1 + t_headway <= A_t2
                model.addConstr(D_t_i[(t1, i)] + t_headway <= A_t_i[(t2, i)] + BIG_M * (1 - o_t_t_i[(t1, t2, i)]), 
                               name=f"station_headway_1_{t1}_{t2}_{i}")
                # If t2 precedes t1: D_t2 + t_headway <= A_t1
                model.addConstr(D_t_i[(t2, i)] + t_headway <= A_t_i[(t1, i)] + BIG_M * o_t_t_i[(t1, t2, i)], 
                               name=f"station_headway_2_{t1}_{t2}_{i}")

    # 13. Delay linearization
    for t in T:
        for i in S:
            model.addConstr(delay_arr[(t, i)] >= A_t_i[(t, i)] - a_t_i[(t, i)], name=f"delay_arr_lin_{t}_{i}")
            model.addConstr(delay_dep[(t, i)] >= D_t_i[(t, i)] - d_t_i[(t, i)], name=f"delay_dep_lin_{t}_{i}")

    # Solve the model
    model.optimize()

    # Extract results
    x_val = {t: x[t].X for t in T}
    y_val = {(t, a): y[(t, a)].X for t in T for a in B if a in D_t[t]}
    z_val = {(t, a, k): z[(t, a, k)].X for t in T for a in D_t[t] for k in K}
    A_t_i_val = {(t, i): A_t_i[(t, i)].X for t in T for i in S}
    D_t_i_val = {(t, i): D_t_i[(t, i)].X for t in T for i in S}
    u_t_a_val = {(t, a): u_t_a[(t, a)].X for t in T for a in D_t[t]}
    o_t_t_a_val = {(t1, t2, a): o_t_t_a[(t1, t2, a)].X for a in A for t1 in [t for t in T if a in D_t[t]] for t2 in [t for t in T if a in D_t[t]] if t1 < t2}
    w_t_a_val = {(t, a): w_t_a[(t, a)].X for t in T for a in D_t[t]}
    e_t_a_val = {(t, a): e_t_a[(t, a)].X for t in T for a in D_t[t]}
    delay_arr_val = {(t, i): delay_arr[(t, i)].X for t in T for i in S}
    delay_dep_val = {(t, i): delay_dep[(t, i)].X for t in T for i in S}

    return {
        "model": model,
        "x": x_val,
        "y": y_val,
        "z": z_val,
        "A_t_i": A_t_i_val,
        "D_t_i": D_t_i_val,
        "u_t_a": u_t_a_val,
        "o_t_t_a": o_t_t_a_val,
        "w_t_a": w_t_a_val,
        "e_t_a": e_t_a_val,
        "delay_arr": delay_arr_val,
        "delay_dep": delay_dep_val,
        "objective": model.ObjVal
    }
